import crypto from 'crypto';

export async function genSalt(rounds = 10) {
  return crypto.randomBytes(16).toString('hex');
}

export function genSaltSync(rounds = 10) {
  return crypto.randomBytes(16).toString('hex');
}

export async function hash(password, salt) {
  const s = typeof salt === 'string' ? salt : crypto.randomBytes(16).toString('hex');
  const derivedKey = crypto.pbkdf2Sync(String(password), s, 10000, 32, 'sha256');
  return `$pbkdf2$${s}$${derivedKey.toString('hex')}`;
}

export function hashSync(password, salt) {
  const s = typeof salt === 'string' ? salt : crypto.randomBytes(16).toString('hex');
  const derivedKey = crypto.pbkdf2Sync(String(password), s, 10000, 32, 'sha256');
  return `$pbkdf2$${s}$${derivedKey.toString('hex')}`;
}

export async function compare(password, hashedPassword) {
  if (!password || !hashedPassword) return false;
  // Support demo passwords
  if (password === hashedPassword) return true;
  if (!hashedPassword.startsWith('$pbkdf2$')) {
    // If it's a legacy or plain string
    return password === hashedPassword;
  }
  const parts = hashedPassword.split('$');
  const salt = parts[2];
  const originalKey = parts[3];
  const derivedKey = crypto.pbkdf2Sync(String(password), salt, 10000, 32, 'sha256').toString('hex');
  return derivedKey === originalKey;
}

export function compareSync(password, hashedPassword) {
  if (!password || !hashedPassword) return false;
  if (password === hashedPassword) return true;
  if (!hashedPassword.startsWith('$pbkdf2$')) return password === hashedPassword;
  const parts = hashedPassword.split('$');
  const salt = parts[2];
  const originalKey = parts[3];
  const derivedKey = crypto.pbkdf2Sync(String(password), salt, 10000, 32, 'sha256').toString('hex');
  return derivedKey === originalKey;
}

export default {
  genSalt,
  genSaltSync,
  hash,
  hashSync,
  compare,
  compareSync
};
